%result = PlateHeatMap([10, 0, -30 , 0 , 20],100, 200, 100, 1000, 100,50);

fs = 2000;

plate = [100,100, 1];

transmitter = [42,12,0.5];

receiver = [85,67,0.5];

response = acousticRoomResponse(plate,transmitter,receiver,SampleRate=fs);

t = (0:1:numel(response)-1)/fs;

%Plot noiseless impulse response 

plot(t,response); %[output:2e9673fd]


%Create input signal


input_signal = ones(1,300);

signalStart = 120;

signalEnd = 150;

input_signal(1:signalStart) = 0;

input_signal(signalEnd:end) = 0;

sent_signal = PlateHeatMap(downsample(input_signal,downsampleRate),100, 100, 800, 200, transmitter(2),transmitter(1)); %[output:20aa6237]

for index = 1:1:800

    %point(index) = signal(1,1,index);

    plate_received_signal(index) = signal(receiver(2),receiver(1),index);
end

plot(transpose(plate_received_signal)) %[output:1b2936f5]

xlabel 'Sample' %[output:1b2936f5]
ylabel 'Magnitude' %[output:1b2936f5]
title('Received Signal from Matrix Method') %[output:1b2936f5]

%Received signal from impulse response

received_signal = (awgn(conv(response,input_signal),2,'measured'));

%Make a time vector for the convolved signal

t2 = (0:numel(received_signal)-1)/fs;

plot(t2,received_signal) %[output:3bb374d2]

xlabel 'Sample' %[output:3bb374d2]
ylabel 'Magnitude' %[output:3bb374d2]
title('Received Signal from acousticRoomResponse Method') %[output:3bb374d2]

returnSignal = fliplr(received_signal);

returnSignal = returnSignal(4745:end);

%%
%Animate the impulse on the plate in 3D

downsampleRate = 2;

signal = PlateHeatMap(downsample(returnSignal,downsampleRate),100, 100, 800, 200, receiver(2),receiver(1)); %[output:85cc514c]

%%
%Code to test my matrix method compared to acousticRoomResponse

for index = 1:1:800

    point(index) = signal(transmitter(2),transmitter(1),index);

end

plot(transpose(point)) %[output:916c105b]

xlabel 'Sample' %[output:916c105b]
ylabel 'Magnitude' %[output:916c105b]
title('Time Reversed Response from Matrix Method') %[output:916c105b]

plot(conv(returnSignal,response)) %[output:32c69dd0]

xlabel 'Sample' %[output:32c69dd0]
ylabel 'Magnitude' %[output:32c69dd0]
title('Time Reversed Response from acousticRoomResponse') %[output:32c69dd0]

%%
%Code to test energy detector function

x = linspace(0,2*pi,1000);
input = sin(x);

output = EnergyDetector(input,2,10); %[output:7922b57e]

plot(output) %[output:3a267c9b]

%%
%Test impulse response matrix

ImpulseMatrix(20,10,3,3,4,2000);

